1	// Package cmdsuggest renders the command-suggestion list shown under the
2	// command line (DEVDESK-89). Rendering is pure: state in, lines out.
3	package cmdsuggest
4	
5	import (
6		"fmt"
7		"strings"
8	
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// MaxVisibleRows is the ceiling on suggestion rows shown at once.
17	const MaxVisibleRows = 8
18	
19	// Row is one suggestion; Current marks the view that is open now.
20	type Row struct {
21		Entry   command.Entry
22		Current bool
23		// Arg, when non-nil, makes this an argument row: Entry is ignored.
24		Arg *command.ArgSuggestion
25	}
26	
27	// Frame selects the corners of the bottom rule.
28	type Frame int
29	
30	const (
31		// FrameJoined draws ├─┤ (the list sits above more viewport content).
32		FrameJoined Frame = iota
33		// FrameClosed draws └─┘.
34		FrameClosed
35	)
36	
37	// Input is everything Render needs.
38	type Input struct {
39		Rows   []Row
40		Total  int
41		Query  string
42		Cursor int // -1 means no highlighted row
43		Offset int
44		Notice string
45		// Heading replaces the "N of M" count in the filet (argument stage).
46		Heading string
47		// Empty is the message shown when there are no rows and Loading is false.
48		Empty string
49		// Loading shows "Loading contexts…" in place of the rows.
50		Loading bool
51		Width   int
52		Visible int
53		Frame   Frame
54	}
55	
56	// Layout holds column widths in cells.
57	type Layout struct{ Marker, Name, Alias, Desc int }
58	
59	// Pair is a foreground/background combination the list paints.
60	type Pair struct {
61		Name   string
62		Fg, Bg lipgloss.Color
63	}
64	
65	// Layout constants, in cells. The widths below are the whole grid: a line is
66	// a border, a one-cell margin, the columns, then fill up to the other border.
67	const (
68		margin        = 1
69		markerWidth   = 2
70		minDescWidth  = 20
71		minAliasWidth = 34 // narrowest terminal that still shows the alias column
72		wideWidth     = 100
73		aliasSep      = " · "
74		currentTag    = "(current)"
75		ellipsis      = "…"
76		// minRenderWidth is the narrowest width that holds a frame, a margin, a
77		// marker and one name cell.
78		minRenderWidth = 6
79	)
80	
81	// VisibleRows returns how many list rows fit: the matches, at least one row
82	// (the "no match" line), capped by MaxVisibleRows and by the usable height
83	// minus the filet.
84	func VisibleRows(matches, usable int) int {
85		return max(min(max(matches, 1), MaxVisibleRows, usable-1), 0)
86	}
87	
88	// Window returns the first visible row so that cursor stays in view. The
89	// window never wraps and, with no highlighted row, keeps the current offset.
90	func Window(cursor, offset, visible int) int {
91		offset = max(offset, 0)
92		if cursor < 0 || visible <= 0 {
93			return offset
94		}
95		switch {
96		case cursor < offset:
97			return cursor
98		case cursor >= offset+visible:
99			return cursor - visible + 1
100		}
101		return offset
102	}
103	
104	// Columns returns the column widths for a terminal width. Columns leave from
105	// the right: description first, then alias; the name alone remains.
106	func Columns(width int) Layout {
107		l := Layout{Marker: markerWidth}
108		if width < minAliasWidth {
109			l.Name = max(width-6, 1)
110			return l
111		}
112		l.Name, l.Alias = 15, 14
113		if width >= wideWidth {
114			l.Name, l.Alias = 18, 18
115		}
116		if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
117			l.Desc = desc
118		}
119		return l
120	}
121	
122	// first returns the index of the first row drawn, kept inside the list.
123	func first(in Input) int {
124		return max(min(in.Offset, len(in.Rows)-max(in.Visible, 0)), 0)
125	}
126	
127	// FiletLabel returns the text of the bottom rule: the notice as a warning
128	// when there is one, otherwise the count with what scrolled out of view.
129	func FiletLabel(in Input) string {
130		if in.Notice != "" {
131			return theme.IconWarning + " " + in.Notice
132		}
133		in.Visible = max(in.Visible, 0)
134		label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
135		if strings.TrimSpace(in.Query) == "" {
136			label = fmt.Sprintf("%d available", len(in.Rows))
137		}
138		start := first(in)
139		if above := start; above > 0 {
140			label += fmt.Sprintf(" · ▲ %d more", above)
141		}
142		if below := len(in.Rows) - start - in.Visible; below > 0 {
143			label += fmt.Sprintf(" · ▼ %d more", below)
144		}
145		return label
146	}
147	
148	// look is one foreground/background combination, read from the theme at call
149	// time so that a theme applied after start-up is honored.
150	type look struct {
151		name string
152		fg   lipgloss.Color
153		bg   lipgloss.Color
154		bold bool
155	}
156	
157	func (k look) style() lipgloss.Style {
158		return lipgloss.NewStyle().Foreground(k.fg).Background(k.bg).Bold(k.bold)
159	}
160	
161	func rowLook() look {
162		return look{name: "row", fg: theme.ColorText, bg: theme.ColorBackground}
163	}
164	
165	func highlightLook() look {
166		return look{name: "highlighted row", fg: theme.ColorText, bg: theme.ColorTableLineSelected, bold: true}
167	}
168	
169	func filetLook() look {
170		return look{name: "filet label", fg: theme.ColorText, bg: theme.ColorBackground}
171	}
172	
173	func warningLook() look {
174		return look{name: "filet warning", fg: theme.ColorFooterWarn, bg: theme.ColorBackground, bold: true}
175	}
176	
177	// Palette lists every text pair the list paints, for the contrast test. The
178	// frame characters are decoration and carry no information, so they are not
179	// listed.
180	func Palette() []Pair {
181		var out []Pair
182		for _, k := range []look{rowLook(), highlightLook(), filetLook(), warningLook()} {
183			out = append(out, Pair{Name: k.name, Fg: k.fg, Bg: k.bg})
184		}
185		return out
186	}
187	
188	// Render returns Visible list rows followed by the bottom rule, each exactly
189	// Width cells wide. Every line is assembled from separately styled segments;
190	// no already-styled text is ever cut.
191	func Render(in Input) []string {
192		in.Visible = max(in.Visible, 0)
193		if in.Width < minRenderWidth {
194			return degenerate(in)
195		}
196		inner := max(in.Width-2, 0)
197		layout := Columns(in.Width)
198		border := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
199		side := border.Render("│")
200	
201		lines := make([]string, 0, in.Visible+1)
202		if len(in.Rows) == 0 {
203			for i := 0; i < in.Visible; i++ {
204				body := theme.EmptyLineBg(inner)
205				if i == 0 {
206					body = row(noMatchText(in.Query), layout, inner, false)
207				}
208				lines = append(lines, side+body+side)
209			}
210		} else {
211			start := first(in)
212			for i := 0; i < in.Visible; i++ {
213				idx := start + i
214				if idx >= len(in.Rows) {
215					lines = append(lines, side+theme.EmptyLineBg(inner)+side)
216					continue
217				}
218				lines = append(lines, side+row(columnsOf(in.Rows[idx], layout), layout, inner, idx == in.Cursor)+side)
219			}
220		}
221		return append(lines, filet(in, inner, border))
222	}
223	
224	// degenerate renders the lines of a terminal too narrow for a frame: blank
225	// background lines and a bare rule, each exactly Width cells (possibly zero).
226	func degenerate(in Input) []string {
227		w := max(in.Width, 0)
228		lines := make([]string, 0, in.Visible+1)
229		for i := 0; i < in.Visible; i++ {
230			lines = append(lines, theme.EmptyLineBg(w))
231		}
232		rule := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
233		return append(lines, rule.Render(strings.Repeat("─", w)))
234	}
235	
236	// cells is the plain text of each column of one row.
237	// A message spans every column.
238	type cells struct{ name, alias, desc, message string }
239	
240	func noMatchText(query string) cells {
241		return cells{message: fmt.Sprintf("No match for %q", query)}
242	}
243	
244	// columnsOf returns the plain text of a row for a layout. The current marker
245	// leads the description, or stands in for the aliases when the description
246	// is hidden; it is dropped when neither column exists.
247	func columnsOf(r Row, l Layout) cells {
248		c := cells{
249			name:  r.Entry.Label(),
250			alias: strings.Join(r.Entry.Aliases, aliasSep),
251			desc:  r.Entry.Description,
252		}
253		if r.Current {
254			switch {
255			case l.Desc > 0:
256				c.desc = strings.TrimSpace(currentTag + " " + c.desc)
257			case l.Alias > 0:
258				c.alias = currentTag
259			}
260		}
261		return c
262	}
263	
264	// fit truncates plain text to leave one cell of air inside its column and
265	// pads it to the full width.
266	func fit(text string, width int) string {
267		if width <= 0 {
268			return ""
269		}
270		if lipgloss.Width(text) > width-1 {
271			text = ansi.Truncate(text, max(width-1, 1), ellipsis)
272		}
273		return text + strings.Repeat(" ", max(width-lipgloss.Width(text), 0))
274	}
275	
276	// row assembles one list line from styled segments, filled up to inner cells.
277	// A highlighted row fills with its own background so it reaches the border.
278	func row(c cells, l Layout, inner int, highlighted bool) string {
279		k, marker := rowLook(), strings.Repeat(" ", markerWidth)
280		if highlighted {
281			k, marker = highlightLook(), theme.IconCircleSmall+" "
282		}
283		st := k.style()
284		body := fit(c.name, l.Name) + fit(c.alias, l.Alias) + fit(c.desc, l.Desc)
285		if c.message != "" {
286			body = fit(c.message, max(inner-margin-markerWidth, 0))
287		}
288		plain := strings.Repeat(" ", margin) + marker + body
289		if w := lipgloss.Width(plain); w < inner {
290			plain += strings.Repeat(" ", inner-w)
291		}
292		return st.Render(plain)
293	}
294	
295	// filet builds the bottom rule with its label.
296	func filet(in Input, inner int, border lipgloss.Style) string {
297		left, right := "├", "┤"
298		if in.Frame == FrameClosed {
299			left, right = "└", "┘"
300		}
301		k := filetLook()
302		if in.Notice != "" {
303			k = warningLook()
304		}
305		label := ansi.Truncate(FiletLabel(in), max(inner-3, 0), ellipsis)
306		dashes := max(inner-2-lipgloss.Width(label)-1, 0)
307		return border.Render(left+"─ ") + k.style().Render(label) +
308			border.Render(" "+strings.Repeat("─", dashes)+right)
309	}
