4		"fmt"
5		"strings"
6		"testing"
7	
8		"github.com/charmbracelet/lipgloss"
9		"github.com/charmbracelet/x/ansi"
10	
11		"github.com/anthnel/devdesk/internal/command"
12		"github.com/anthnel/devdesk/internal/ui/testutil"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// argRow builds an argument row; current adds the "(current)" tag.
17	func argRow(value, note string, current bool) Row {
18		return Row{Arg: &command.ArgSuggestion{Value: value, Note: note}, Current: current}
19	}
20	
21	func ctxRows() []Row {
22		return []Row{
23			argRow("web", "", false),
24			argRow("work", "", true),
25			argRow("-", "Previous context", false),
26			argRow("new", "Create a context", false),
27		}
28	}
29	
30	func manyCtx(n int) []Row {
31		rows := make([]Row, n)
32		for i := range rows {
33			rows[i] = argRow(fmt.Sprintf("ctx%02d", i), "", false)
34		}
35		return rows
36	}
37	
38	func argInput(width int) Input {
39		rows := ctxRows()
40		return Input{Rows: rows, Total: 5, Heading: "Contexts · 4 of 5", Cursor: -1, Width: width, Visible: len(rows)}
41	}
42	
43	func hasIcon(l string) bool { return strings.Contains(l, theme.IconCircleSmall) }
44	
45	func TestArgFiletShowsHeadingAndRowsShowValues(t *testing.T) {
46		lines := plain(render(t, argInput(80)))
47		last := lines[len(lines)-1]
48		if !strings.Contains(last, "Contexts · 4 of 5") {
49			t.Errorf("filet lacks the heading: %q", last)
50		}
51		if strings.Contains(last, "available") || strings.Contains(last, "of 17") {
52			t.Errorf("filet still shows the command count: %q", last)
53		}
54		for i, want := range []string{"web", "work", "-", "new"} {
55			if !strings.Contains(lines[i], want) {
56				t.Errorf("row %d = %q, want it to contain %q", i, lines[i], want)
57			}
58		}
59	}
60	
61	func TestArgRowShowsCurrentAsTextAfterTheName(t *testing.T) {
62		lines := plain(render(t, argInput(80)))
63		if !strings.Contains(lines[1], "work (current)") {
